import{_ as r,o as t,c as a,a5 as s}from"./chunks/framework.BmD0ICqc.js";const i="/study/images/graphics/shader-inputs-and-uniforms.svg",f=JSON.parse('{"title":"シェーダーへ渡すデータ — 頂点属性・uniform・テクスチャ","description":"","frontmatter":{"title":"シェーダーへ渡すデータ — 頂点属性・uniform・テクスチャ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"三角形の位置とUV、共通の色を例に、頂点属性、ステージ間の補間、uniformと定数バッファ、テクスチャとサンプラーの渡し方を説明する。","aliases":["シェーダー入力","頂点属性","attribute","varying","uniform","定数バッファ","cbuffer","セマンティクス","binding","バインディング","テクスチャ","サンプラー"],"verification":"KhronosのGLSL ES 3.00仕様、MDNのWebGL API、MicrosoftのHLSL定数・配置とD3D12バインディング資料に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/shader/shader-inputs-and-uniforms.md","filePath":"graphics/shader/shader-inputs-and-uniforms.md"}'),n={name:"graphics/shader/shader-inputs-and-uniforms.md"};function o(d,e,l,h,c,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="シェーダーへ渡すデータ-—-頂点属性・uniform・テクスチャ" tabindex="-1">シェーダーへ渡すデータ — 頂点属性・uniform・テクスチャ <a class="header-anchor" href="#シェーダーへ渡すデータ-—-頂点属性・uniform・テクスチャ" aria-label="Permalink to &quot;シェーダーへ渡すデータ — 頂点属性・uniform・テクスチャ&quot;">​</a></h1><p>三角形の形を保ったまま全体の色を変えるとき、シェーダーには「頂点ごとに違う位置」と「描画に共通する色」が必要です。コードに書く変数がどこから来るかを見分けると、CPU側で何を用意するかが分かります。<a href="/study/graphics/shader/shader-first-steps.html">シェーダーの基礎</a></p><h2 id="データを使う範囲から見る" tabindex="-1">データを使う範囲から見る <a class="header-anchor" href="#データを使う範囲から見る" aria-label="Permalink to &quot;データを使う範囲から見る&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入力の種類</th><th>この例の値</th><th>用意するもの</th></tr></thead><tbody><tr><td><strong>頂点属性</strong></td><td>各頂点の位置とUV。</td><td>頂点バッファと、その中の値を取り出す配置の指定。</td></tr><tr><td><strong>uniform・定数</strong></td><td>三角形全体に掛ける色、横方向への移動量。</td><td>CPU側で指定する共通の値。HLSLでは定数バッファなどにまとめる。</td></tr><tr><td><strong>テクスチャ</strong></td><td>表面の色や粗さなどを記録したデータ。</td><td>GPUから参照するデータと、読む場所の接続。</td></tr><tr><td><strong>サンプラー</strong></td><td>テクスチャの拡縮や範囲外をどう読むか。</td><td>フィルタリングや繰り返しなどの設定。</td></tr></tbody></table><p>CPU側で値を用意し、シェーダーが使う入力へ対応付ける操作を<strong>バインド</strong>と呼びます。どの値を使うかと、どの入力へ接続するかを合わせます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/resource-binding" target="_blank" rel="noreferrer">Microsoftのリソースバインディング</a></p><figure class="study-figure"><img src="'+i+`" alt="CPU側が位置とUVの頂点バッファ、共通の色と移動量、テクスチャとサンプラーを用意する。頂点属性を頂点シェーダーへ渡し、UVを補間してピクセル側へ渡す。uniformや定数バッファの値と参照するデータを使って色を計算する。" width="760" height="490" loading="lazy"><figcaption>データの配置と接続を用意してから描画します。テクスチャは、今回の三角形の実践を発展させる場合の入力です。<a href="/study/images/graphics/shader-inputs-and-uniforms.svg" target="_blank" rel="noopener noreferrer">シェーダー入力の図を拡大</a></figcaption></figure><h2 id="頂点属性は、バッファのどこから読むかを決める" tabindex="-1">頂点属性は、バッファのどこから読むかを決める <a class="header-anchor" href="#頂点属性は、バッファのどこから読むかを決める" aria-label="Permalink to &quot;頂点属性は、バッファのどこから読むかを決める&quot;">​</a></h2><p>実践の頂点は、二つの数で位置を表す<code>a_position</code>と、二つの数でUVを表す<code>a_uv</code>を持ちます。例えば各頂点を<code>位置X・位置Y・U・V</code>の順に32ビット浮動小数点数で並べるなら、次の頂点までは16バイト、UVの開始は頂点先頭から8バイトです。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGLRenderingContext/vertexAttribPointer" target="_blank" rel="noreferrer">WebGLのvertexAttribPointer</a></p><p>この間隔を<strong>ストライド</strong>、先頭からの位置を<strong>オフセット</strong>と呼びます。WebGLでは、対応する属性の場所を調べるか、GLSL ESの<code>layout(location=...)</code>などで決め、型・個数・ストライド・オフセットを指定します。入力名を<code>a_position</code>と書くことに加え、CPU側でその入力とバッファを接続します。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGLRenderingContext/vertexAttribPointer" target="_blank" rel="noreferrer">属性の接続と有効化</a> · <a href="/study/graphics/mesh/vertex-and-index-input.html">頂点とインデックス入力の詳解</a></p><h2 id="頂点から渡したuvは、三角形の途中で補間する" tabindex="-1">頂点から渡したUVは、三角形の途中で補間する <a class="header-anchor" href="#頂点から渡したuvは、三角形の途中で補間する" aria-label="Permalink to &quot;頂点から渡したUVは、三角形の途中で補間する&quot;">​</a></h2><p>WebGL 2で使うGLSL ES 3.00では、頂点側の<code>out vec2 v_uv</code>と、フラグメント側の<code>in vec2 v_uv</code>などを対応させます。頂点側が出したUVをもとに、三角形の内部で使うUVを求めます。こうしたステージ間で渡す値は、<strong>varying</strong>とも呼ばれます。<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/GLSL_ES_Specification_3.00.pdf" target="_blank" rel="noreferrer">GLSL ES 3.00の入出力と補間 §4.3</a></p><p>通常の浮動小数点数の入出力には、既定で透視補正を含む<strong>smooth補間</strong>を使います。実践では頂点のクリップ座標の<code>w</code>をすべて<code>1</code>にしているため、UVの変化を画面上の三角形で追いやすくしています。<code>flat</code>を指定する場合などは、受け渡しの規則が変わります。<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/GLSL_ES_Specification_3.00.pdf" target="_blank" rel="noreferrer">GLSL ESの補間 §4.3.9</a> · <a href="/study/graphics/basics/transforms-and-cameras.html">座標と投影の基礎</a></p><h2 id="uniformで、描画に共通する値を渡す" tabindex="-1">uniformで、描画に共通する値を渡す <a class="header-anchor" href="#uniformで、描画に共通する値を渡す" aria-label="Permalink to &quot;uniformで、描画に共通する値を渡す&quot;">​</a></h2><p>実践のフラグメント側には次の共通値を渡します。<code>u_tint</code>はRGBの三つの成分、<code>u_useUv</code>は白とUVの色を混ぜる割合です。頂点側には横へ動かす<code>u_offset</code>も渡します。</p><div class="language-glsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">glsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uniform</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> vec3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> u_tint;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uniform</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> u_useUv;</span></span></code></pre></div><p>WebGLでは、リンクした<strong>プログラムオブジェクト</strong>ごとにuniformの値を持ちます。<code>getUniformLocation</code>で対象の場所を取得し、<code>useProgram</code>で選んだプログラムのuniformへ、<code>uniform3f</code>などのAPIで値を設定します。設定した値は、同じプログラムを次に使うときも保持されます。再リンクが成功すると初期値へ戻ります。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGLRenderingContext/uniform" target="_blank" rel="noreferrer">uniformの値と保持期間</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGLRenderingContext/getUniformLocation" target="_blank" rel="noreferrer">uniformの場所を取得する</a></p><p>色の操作だけを変えるなら、描画前にuniformを設定して再び描けます。シェーダーのソースを書き換えてコンパイルする操作と、すでにある入力の値を変える操作を区別すると、画面の変化を追えます。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGLRenderingContext/linkProgram" target="_blank" rel="noreferrer">WebGLのプログラムのリンク</a></p><h2 id="hlslでは定数バッファへまとめる例がある" tabindex="-1">HLSLでは定数バッファへまとめる例がある <a class="header-anchor" href="#hlslでは定数バッファへまとめる例がある" aria-label="Permalink to &quot;HLSLでは定数バッファへまとめる例がある&quot;">​</a></h2><p>対応するHLSLの例では、共通の値を次のようにまとめます。<code>tint.rgb</code>が色、<code>controls.x</code>が移動量、<code>controls.y</code>がUVの色を使う割合です。</p><div class="language-hlsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hlsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cbuffer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Parameters : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(b0)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tint;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    float4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> controls;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p><code>b0</code>は、この定数バッファが使う入力の割り当てです。CPU側も、その割り当てに対応するデータを渡します。HLSLの頂点入力は<code>POSITION</code>や<code>TEXCOORD0</code>という<strong>セマンティクス</strong>を使い、CPU側の入力レイアウトと対応させます。頂点側の<code>SV_Position</code>は、ラスタライズに使うクリップ座標を出すためのシステム値です。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-constants" target="_blank" rel="noreferrer">HLSLの定数バッファ</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-semantics" target="_blank" rel="noreferrer">HLSLのセマンティクス</a></p><p>この例の<code>float4</code>は一つ16バイトで、二つの格納データは32バイトです。型を増やすときは、余白である<strong>パディング</strong>や、配列・行列の配置の規則も確認します。D3D12のCBVのサイズ指定などには、格納する値の大きさとは別のアラインメント要件があります。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-packing-rules" target="_blank" rel="noreferrer">HLSLの配置規則</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_constant_buffer_view_desc" target="_blank" rel="noreferrer">D3D12のCBV</a></p><h2 id="テクスチャとサンプラーも、使うものを接続する" tabindex="-1">テクスチャとサンプラーも、使うものを接続する <a class="header-anchor" href="#テクスチャとサンプラーも、使うものを接続する" aria-label="Permalink to &quot;テクスチャとサンプラーも、使うものを接続する&quot;">​</a></h2><p>UVを色として表示する代わりに、UVでテクスチャを参照できます。WebGLの<code>sampler2D</code>には、どのテクスチャユニットを読むかを整数で設定し、そのユニットへテクスチャを接続します。HLSLの<code>Texture2D</code>と<code>SamplerState</code>では、参照するデータと読む設定を別々に指定する形があります。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGL_API/Tutorial/Using_textures_in_WebGL" target="_blank" rel="noreferrer">MDNのWebGLテクスチャ</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-to-sample" target="_blank" rel="noreferrer">HLSLのテクスチャサンプリング</a></p><p>テクスチャを読む場所はUVが示し、周囲の値の混ぜ方や範囲外の扱いはサンプラーなどの設定で決まります。詳しい役割は<a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダー</a>で確認できます。</p><h2 id="コードの準備と、描画時の設定を追う" tabindex="-1">コードの準備と、描画時の設定を追う <a class="header-anchor" href="#コードの準備と、描画時の設定を追う" aria-label="Permalink to &quot;コードの準備と、描画時の設定を追う&quot;">​</a></h2><p>WebGLではシェーダーをコンパイルしてプログラムをリンクし、描画時にはプログラム、頂点入力、uniform、テクスチャなどを設定します。D3D12では、コンパイルしたシェーダーや描画設定をPSOへまとめ、コマンドでPSOやリソースの接続を指定します。<a href="https://developer.mozilla.org/en-US/docs/Web/API/WebGLRenderingContext/linkProgram" target="_blank" rel="noreferrer">WebGLのリンク</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/managing-graphics-pipeline-state-in-direct3d-12" target="_blank" rel="noreferrer">D3D12のPSO</a></p><p>実際の値を変えて追うには、<a href="/study/practice/graphics/shader-first-steps.html">三角形の色と位置を変える実践</a>へ進みます。バッファやテクスチャをGPUで使い終える時点は、<a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命</a>で扱います。</p>`,28)])])}const u=r(n,[["render",o]]);export{f as __pageData,u as default};
